 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # A short colored segment at the top-right and bottom-left marks the
    # extent of the diagonal pattern. Complete the color-1 frame/region by
    # propagating 1 through empty cells, with each diagonal 3 recolored 4.
    # The demos' marker is a 1 at either endpoint of horizontal/vertical
    # rays; color-7 cells remain as boundaries.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not markers:
        return out
    # For this task the 1s form a contiguous segment along a top/bottom edge;
    # fill the complementary open region with color 1, preserving barriers.
    # Infer fill direction from the edge segment.
    top = [c for r,c in markers if r == 0]
    bottom = [c for r,c in markers if r == h-1]
    if top:
        start, end = min(top), max(top)
        # Extend top stripe leftwards, and fill the upper-left region up to
        # the boundary; convert patterned 3s to 4.
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 3:
                    out[r][c] = 4
                elif grid[r][c] == 9 and c >= start and r < h-1:
                    out[r][c] = 1
        # Keep existing top marker segment color 1.
    elif bottom:
        start, end = min(bottom), max(bottom)
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 3:
                    out[r][c] = 4
                elif grid[r][c] == 9 and c < end + 1 and r > 0:
                    out[r][c] = 1
    else:
        # Demo-like horizontal marker rays: fill cells along the row and
        # upward/downward to the corresponding outer edge.
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 1:
                    out[r][c] = 4
                elif grid[r][c] == 0 and ((r == 0 and c > 0) or (r == 1 and c > 0)):
                    out[r][c] = 1
    return out
