    out = [row[:] for row in grid]
    # The isolated motif color acts as a diagonal guide. Color its cells 4
    # and extend the diagonal field on the side indicated by the long 1 bars.
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in marks:
        out[r][c] = 4
    if marks:
        # The 1 bars at opposite corners indicate an inward diagonal wedge.
        # Fill rightward of the guide, interpolating between the guide marks.
        line = {}
        for r, c in marks:
            line[r] = c
        for r in range(h):
            if r in line:
                b = line[r]
            else:
                lo = max((rr for rr in line if rr < r), default=None)
                hi = min((rr for rr in line if rr > r), default=None)
                if lo is None:
                    b = line[hi] + (hi-r)
                elif hi is None:
                    b = line[lo] + (r-lo)
                else:
                    b = round(line[lo] + (line[hi]-line[lo])*(r-lo)/(hi-lo))
            for c in range(max(0,b+1),w):
                if grid[r][c] == 9:
                    out[r][c] = 1
    return out
