        runs.append((side, start, end, color))
        if side == 'left':
            edge_cells.update((r, 0) for r in range(start, end + 1))
        elif side == 'right':
            edge_cells.update((r, w - 1) for r in range(start, end + 1))
        elif side == 'top':
            edge_cells.update((0, c) for c in range(start, end + 1))
        else:
            edge_cells.update((h - 1, c) for c in range(start, end + 1))

    def scan(vals, side):
        i = 0
        while i < len(vals):
            color = vals[i]
            if color == background:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            if j - i >= 2:
