    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    edges = [
        ("top", grid[0]),
        ("bottom", grid[h - 1]),
        ("left", [grid[r][0] for r in range(h)]),
        ("right", [grid[r][w - 1] for r in range(h)]),
    ]
    for side, values in edges:
        i = 0
