{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    values = [v for row in grid for v in row]
    bg = max(set(values), key=values.count)
    # The sparse non-background, non-edge color is the ray color. Markers
    # themselves become 4; endpoint cells of each edge run project inward.
    edge_colors = {grid[0][c] for c in range(w)} | {grid[h-1][c] for c in range(w)}
    edge_colors |= {grid[r][0] for r in range(h)} | {grid[r][w-1] for r in range(h)}
    interior = [v for v in set(values) if v != bg and v not in edge_colors]
    marker_color = interior[0] if interior else None
    marks = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker_color}
    for r,c in marks:
        out[r][c] = 4
    def runs(vals):
        i=0
        while i<len(vals):
            if vals[i] == bg:
                i+=1; continue
            j=i+1
            while j<len(vals) and vals[j]==vals[i]: j+=1
            if j-i >= 2:
                yield i,j-1
            i=j
    # Project from the two endpoints of each run on each outer edge.
    for a,b in runs(grid[0]):
        for c in {a,b}:
            for r in range(1,h):
                if (r,c) in marks:
                    out[r][c]=4; break
                if grid[r][c] != bg: break
                out[r][c]=marker_color
    for a,b in runs(grid[h-1]):
        for c in {a,b}:
            for r in range(h-2,-1,-1):
                if (r,c) in marks:
                    out[r][c]=4; break
                if grid[r][c] != bg: break
                out[r][c]=marker_color
    for a,b in runs([grid[r][0] for r in range(h)]):
        for r in {a,b}:
            for c in range(1,w):
                if (r,c) in marks:
                    out[r][c]=4; break
                if grid[r][c] != bg: break
                out[r][c]=marker_color
    for a,b in runs([grid[r][w-1] for r in range(h)]):
        for r in {a,b}:
            for c in range(w-2,-1,-1):
                if (r,c) in marks:
                    out[r][c]=4; break
                if grid[r][c] != bg: break
                out[r][c]=marker_color
