    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    # Rare interior color denotes the points whose projections are drawn.
    border = set(grid[0] + grid[-1] + [row[0] for row in grid] + [row[-1] for row in grid])
    guide_candidates = [v for v in set(vals) if v != bg and v not in border]
    guide = min(guide_candidates, key=vals.count) if guide_candidates else min((v for v in set(vals) if v != bg), key=vals.count)
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == guide]

    def runs(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(line) and line[j] == line[i]:
                j += 1
            if j - i >= 2:
                result.append((i, j, line[i]))
            i = j
        return result

    # Opposite matching edge bars pair positions at equal offsets. A marker
    # aligned with one bar projects toward that bar; its paired offset draws
    # a complete stripe inward from the opposite bar.
    orientations = [
        (runs(grid[0]), runs(grid[-1]), "top", "bottom"),
        (runs([grid[r][0] for r in range(h)]), runs([grid[r][-1] for r in range(h)]), "left", "right"),
    ]
    for side_a, side_b, first_side, second_side in orientations:
        for a in side_a:
            for b in side_b:
                if a[2] != b[2] or a[1] - a[0] != b[1] - b[0]:
                    continue
                for r, c in marks:
                    pos = c if first_side in ("top", "bottom") else r
                    if a[0] <= pos < a[1]:
                        source, target, source_side = a, b, first_side
                    elif b[0] <= pos < b[1]:
                        source, target, source_side = b, a, second_side
                    else:
                        continue
                    mapped = target[0] + pos - source[0]
                    # Fill from the guide point toward its associated boundary.
                    if source_side == "top":
                        for rr in range(r - 1, 0, -1):
                            if grid[rr][c] == bg: out[rr][c] = guide
                        for rr in range(1, h - 1):
                            if grid[rr][mapped] == bg: out[rr][mapped] = guide
                    elif source_side == "bottom":
                        for rr in range(r + 1, h - 1):
                            if grid[rr][c] == bg: out[rr][c] = guide
                        for rr in range(1, h - 1):
                            if grid[rr][mapped] == bg: out[rr][mapped] = guide
                    elif source_side == "left":
                        for cc in range(c - 1, 0, -1):
                            if grid[r][cc] == bg: out[r][cc] = guide
                        for cc in range(1, w - 1):
                            if grid[mapped][cc] == bg: out[mapped][cc] = guide
                    else:
                        for cc in range(c + 1, w - 1):
                            if grid[r][cc] == bg: out[r][cc] = guide
                        for cc in range(1, w - 1):
                            if grid[mapped][cc] == bg: out[mapped][cc] = guide
    for r, c in marks:
        out[r][c] = 4
    return out
